import { writeFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

const __dirname = dirname(fileURLToPath(import.meta.url));

export function saveSVG(filename, svgContent) {
  const finalSVG = [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<!-- GENERATED by builder pipeline — DO NOT EDIT MANUALLY -->',
    svgContent
  ].join('\n');
  
  writeFileSync(join(__dirname, '../../', filename), finalSVG, 'utf8');
  console.log(`✔ Generated ${filename}`);
}

export function wrapStandalone(viewBox, innerContent) {
  return [
    `<svg viewBox="${viewBox}" xmlns="http://www.w3.org/2000/svg">`,
    innerContent,
    '</svg>'
  ].join('\n');
}

export function wrapResponsive(viewWidth, viewHeight, cssHeight, innerContent) {
  return [
    `<svg class="brand-logo" viewBox="0 0 ${viewWidth.toFixed(1)} ${viewHeight.toFixed(1)}"`,
    '     xmlns="http://www.w3.org/2000/svg"',
    `     style="height: ${cssHeight}; width: auto; display: block; overflow: visible; flex-shrink: 0;">`,
    innerContent,
    '</svg>'
  ].join('\n');
}
